        left = self.visit(node.left)
        right = self.visit(node.right)
        if isinstance(left, str) and isinstance(right, str):
            # Check if both operands are strings and only concatenation is allowed
            if isinstance(node.op, ast.Add):
                return left + right
            raise SyntaxError("Concatenation of non-string values not allowed")
        self.result = left + right
        return self.result

    def visit_Num(self, node):
        self.result = node.n
        return self.result

    def visit_Expr(self, node):
        expr = self.visit(node.value)
        if isinstance(expr, str):
            raise SyntaxError("Expression must be a valid numeric value")
        self.result = expr
        return self.result

    def visit_Assign(self, node):
        raise SyntaxError("Assignment statements are not allowed")

